<?php
if($page==='admin'){
  require_admin();$counts=['locations'=>(int)$pdo->query('SELECT COUNT(*) FROM locations')->fetchColumn(),'bookings'=>(int)$pdo->query('SELECT COUNT(*) FROM bookings')->fetchColumn(),'users'=>(int)$pdo->query("SELECT COUNT(*) FROM users WHERE role='customer'")->fetchColumn(),'revenue'=>(float)$pdo->query("SELECT COALESCE(SUM(total_amount),0) FROM bookings WHERE payment_status='paid' AND status<>'cancelled'")->fetchColumn()];$recent=$pdo->query('SELECT b.*,u.name user_name,l.name location_name FROM bookings b JOIN users u ON u.id=b.user_id JOIN locations l ON l.id=b.location_id ORDER BY b.created_at DESC LIMIT 8')->fetchAll();layout_start('Admin dashboard',true);?>
  <section class="container section"><div class="section-head"><div><span class="eyebrow">Operations</span><h1>Admin overview</h1></div><a class="btn" href="<?=e(app_url(['page'=>'admin-locations','edit'=>'new']))?>">Add location</a></div><div class="stats"><div class="stat"><span>Locations</span><strong><?=$counts['locations']?></strong><small>All storage spots</small></div><div class="stat"><span>Bookings</span><strong><?=$counts['bookings']?></strong><small>All-time reservations</small></div><div class="stat"><span>Customers</span><strong><?=$counts['users']?></strong><small>Registered users</small></div><div class="stat"><span>Paid revenue</span><strong><?=e(money($counts['revenue']))?></strong><small>Paid, non-cancelled</small></div></div><div class="panel"><div class="section-head"><h2>Recent bookings</h2><a href="<?=e(app_url(['page'=>'admin-bookings']))?>">View all</a></div><div class="table-wrap"><table><thead><tr><th>Code</th><th>Customer</th><th>Location</th><th>Status</th><th>Total</th></tr></thead><tbody><?php if(!$recent):?><tr><td colspan="5">No bookings yet.</td></tr><?php else:foreach($recent as $b):?><tr><td><?=e($b['code'])?></td><td><?=e($b['user_name'])?></td><td><?=e($b['location_name'])?></td><td><span class="status status-<?=e($b['status'])?>"><?=e($b['status'])?></span></td><td><?=e(money((float)$b['total_amount']))?></td></tr><?php endforeach;endif;?></tbody></table></div></div></section>
  <?php layout_end();exit;
}
